-- 002 — районы и категории (SRS §2.5, §2.6).
--
-- Сид районов лежит здесь, а не в отдельном скрипте, по одной причине: без 12 полигонов
-- геозабор отклоняет каждую заявку, то есть пустая таблица district — это неработающее
-- приложение, а не «база без данных». Миграция накатывается везде одинаково
-- (docker compose run --rm migrate), и отдельного шага, который можно забыть, не остаётся.
--
-- Геометрия скопирована из data/geo/tashkent-districts.geojson дословно, свойства — оттуда же.
-- Источник и проверки датасета описаны в data/geo/README.md.

CREATE TABLE district (
    code          VARCHAR(32) PRIMARY KEY,
    name_uz       VARCHAR(120) NOT NULL,
    name_ru       VARCHAR(120) NOT NULL,
    name_en       VARCHAR(120) NOT NULL,
    area_ha       INTEGER      NOT NULL,
    bbox_min_lon  DECIMAL(9,6) NOT NULL,
    bbox_min_lat  DECIMAL(9,6) NOT NULL,
    bbox_max_lon  DECIMAL(9,6) NOT NULL,
    bbox_max_lat  DECIMAL(9,6) NOT NULL,
    -- geography, а не geometry: ST_DWithin по нему считает настоящие метры (SRS §3.3).
    geom          geography(MultiPolygon, 4326) NOT NULL
);

-- Вторая и последняя ручная правка сгенерированного SQL во всей схеме: Prisma
-- не описывает GiST (SRS §2.14).
CREATE INDEX district_geom_idx ON district USING GIST (geom);

CREATE TABLE category (
    id         INTEGER      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code       VARCHAR(32)  NOT NULL,
    name_uz    VARCHAR(120) NOT NULL,
    name_ru    VARCHAR(120) NOT NULL,
    sort_order SMALLINT     NOT NULL,
    is_active  BOOLEAN      NOT NULL DEFAULT true
);

-- Имя индекса — то, которое ожидает Prisma от @unique: иначе миграция и схема
-- расходятся на пустом месте и prisma migrate diff показывает ложный дрейф.
CREATE UNIQUE INDEX category_code_key ON category (code);

-- Стартовый набор из docs/domain/glossary.md. Окончательный состав сверяется с бригадой
-- и правится INSERT/UPDATE — без миграции и без передеплоя (SRS §2.5, PRD §12.2).
INSERT INTO category (code, name_uz, name_ru, sort_order) VALUES
    ('roadway_pothole',  'Yoʻl qismidagi chuqur',                  'Яма на проезжей части',                        1),
    ('sidewalk_pothole', 'Piyodalar yoʻlakchasidagi chuqur',       'Яма на тротуаре или пешеходной дорожке',       2),
    ('yard_damage',      'Hovli yoki kvartal ichidagi yoʻl buzilishi', 'Разрушение во дворе или внутриквартальном проезде', 3),
    ('sinkhole',         'Choʻkish yoki oʻpirilish',               'Провал или просадка',                          4),
    ('utility_cover',    'Quduq qopqogʻi',                         'Люк или решётка ливнёвки',                     5),
    ('crack',            'Yoriq',                                  'Трещина в покрытии',                           6),
    ('other',            'Boshqa',                                 'Другое',                                       7);

-- Polygon приводится к MultiPolygon: иначе Мирзо-Улугбекский с эксклавом был бы
-- единственной строкой другого типа и требовал бы отдельной ветки в каждом запросе
